+func (loginURLActionModel) Init() tea.Cmd { return nil }
+
+func (m loginURLActionModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
+	key, ok := msg.(tea.KeyPressMsg)
+	if !ok {
+		return m, nil
+	}
