+	switch key.String() {
+	case "enter", "ctrl+j":
+		m.action = loginURLOpen
+	case "c", "C":
+		m.action = loginURLCopy
+	case "ctrl+c":
+		m.err = context.Canceled
+	default:
+		return m, nil
+	}
