194:func openLoginPromptPTY(t *testing.T) (ptmx, tty, observer *os.File, before *term.State) {
195:	t.Helper()
196:
197:	ptmx, tty, err := pty.Open()
198:	if err != nil {
199:		t.Skipf("cannot open a pty here: %v", err)
200:	}
201:
202:	observerFD, err := unix.Dup(int(tty.Fd()))
203:	if err != nil {
204:		_ = ptmx.Close()
205:		_ = tty.Close()
206:		t.Fatalf("duplicate tty descriptor: %v", err)
207:	}
208:	observer = os.NewFile(uintptr(observerFD), "login-prompt-tty-observer")
209:
210:	before, err = term.GetState(int(observer.Fd()))
211:	if err != nil {
212:		_ = ptmx.Close()
213:		_ = tty.Close()
214:		_ = observer.Close()
215:		t.Fatalf("read initial terminal state: %v", err)
216:	}
217:
218:	return ptmx, tty, observer, before
219:}
